const curatedArticles = [{"slug": "ky-luat-khong-can-gong-thoi-quen-nguyen-tu-20261108", "title": "Kỷ Luật Không Cần Gồng: Bí Mật Sức Mạnh Thói Quen Nguyên Tử", "excerpt": "Thay đổi lớn không đến từ những cú sốc ý chí ngắn hạn, mà bắt nguồn từ những chuyển động 1% mỗi ngày theo triết lý Kaizen. Đúc kết sâu sắc từ video của Better Version.", "thumbnail": "https://traicainghien.com/images/articles/sach-kaizen-1-phan-tram-trai-cai-nghien.webp", "points": ["Từ bỏ ảo tưởng đột phá:** Thay đổi bền vững đến từ những hành vi nhỏ 1% mỗi ngày.", "Quy tắc 2 phút:** Hạ thấp rào cản hành động đến mức não bộ không thể tìm lý do trì hoãn.", "Môi trường định hình thói quen:** Sắp xếp không gian sống để thói quen tốt dễ xảy ra nhất."], "action": "Bắt đầu với phiên bản 2 phút cực nhỏ cho việc bạn đang trì hoãn.", "url": "https://traicainghien.com/bai-viet/ky-luat-khong-can-gong-thoi-quen-nguyen-tu-20261108"}, {"slug": "chua-lanh-nao-bo-khoi-nhun-nao-so-brain-rot-20261108", "title": "Chữa Lành Não Bộ Khỏi Nhũn Não Số: Khôi Phục Khả Năng Tập Trung Sâu", "excerpt": "Tập trung không phải là gồng mình chiến đấu, mà là nghệ thuật làm dịu tâm trí và loại bỏ bẫy kích thích rẻ tiền. Góc nhìn sâu sắc được đúc kết từ video của Hieu The Consul.", "thumbnail": "https://traicainghien.com/images/articles/tinh-deo-than-kinh-sanctuary-zen-watercolor.webp", "points": ["Bản chất của Brain Rot:** Do thụ thể dopamine bị chai sạn trước lượng kích thích video ngắn quá liều, không phải do bạn lười biếng.", "Môi trường quan trọng hơn ý chí:** Cất điện thoại cách xa 2m giúp triệt tiêu 70% các cơn thèm lướt máy vô thức.", "Đơn nhiệm nhịp nhàng:** 45 phút tập trung sâu kết hợp 10 phút nghỉ ngơi không màn hình."], "action": "Dành 2 phút ghi lại cảm giác hiện tại và đặt điện thoại xa tầm mắt 2 mét.", "url": "https://traicainghien.com/bai-viet/chua-lanh-nao-bo-khoi-nhun-nao-so-brain-rot-20261108"}, {"slug": "khi-chi-con-10-phan-tram-nang-luong-giao-an-cho-ngay-kiet-que", "title": "Khi Chỉ Còn 10% Năng Lượng: Giáo Án Cho Một Ngày Kiệt Quệ", "excerpt": "Mở mắt ra thấy đầu nặng trịch, ngực tức nghẹn và chỉ muốn trốn cả thế giới? Đừng ép chiếc chân đang đau phải chạy nước rút. Khám phá cách làm việc nhân văn khi tinh thần chạm đáy.", "thumbnail": "https://traicainghien.com/images/articles/ngay-nang-luong-10-phan-tram-zen-watercolor-v2.webp", "points": ["Một chiếc xe tải chở được 10 tấn hàng vào ngày máy móc hoàn hảo. Nhưng hôm nay động cơ bị hỏng một xi-lanh, tải trọng an toàn của nó chỉ còn 1 tấn. Nếu bạn cố nhồi nhét đủ 10 tấn, bạn không phải là người tài giỏi, bạn đang phá nát chiếc xe.", "Cầu thủ bị đau cơ đi bộ 30 phút quanh sân trong khi đồng đội chạy 90 phút, cậu ấy không thua kém ai cả. Cậu ấy đang hoàn thành xuất sắc 100% giáo án hồi phục của mình.", "Vào một ngày 100% phong độ: Giáo án của bạn là viết xong một bài báo cáo 10 trang, dọn sạch căn nhà, nấu bữa ăn eat-clean và tập gym 1 tiếng."], "action": "Hạ chuẩn mọi mục tiêu xuống mức tối thiểu, cho phép bản thân nghỉ ngơi sớm.", "url": "https://traicainghien.com/bai-viet/khi-chi-con-10-phan-tram-nang-luong-giao-an-cho-ngay-kiet-que"}, {"slug": "dung-flex-doc-sach-vi-sao-doc-nhieu-doi-van-tri-tre", "title": "Bẫy 'Nghiện Đọc': Đọc Hết 50 Cuốn Sách, Sao Cuộc Đời Vẫn Đứng Yên?", "excerpt": "Mua sách theo trend, check-in khoe số lượng, nhưng tâm trí vẫn bất an và cuộc sống dậm chân tại chỗ? Khám phá cạm bẫy 'thượng đẳng tri thức' và nghệ thuật đọc để chuyển hóa đời thực.", "thumbnail": "https://traicainghien.com/images/articles/bay-nghien-doc-50-cuon-sach-zen-watercolor.webp", "points": ["Bạn đọc về thói quen dậy sớm 5h sáng của các triệu phú, bạn cảm thấy mình như đã trở thành người thành đạt.", "Bạn đọc về thuật quản trị cảm xúc, bạn ngỡ rằng mình đã là một bậc thầy thiền định điềm tĩnh.", "Bạn đọc về chiến lược đầu tư tài chính, bạn tưởng tượng mình đã nắm trong tay chìa khóa tự do."], "action": "Chọn đúng 1 ý tưởng hay nhất từ cuốn sách đang đọc và đem ra áp dụng ngay.", "url": "https://traicainghien.com/bai-viet/dung-flex-doc-sach-vi-sao-doc-nhieu-doi-van-tri-tre"}, {"slug": "bang-dieu-khien-nao-bo-4-hoa-chat-than-kinh-ky-luat-dinh-cao", "title": "Bảng Điều Khiển Não Bộ: 4 Hóa Chất Tạo Nên Kỷ Luật Đỉnh Cao", "excerpt": "Dopamine, Epinephrine, Acetylcholine và Serotonin: Cách làm chủ 4 hóa chất thần kinh để khôi phục năng lượng, tập trung và kỷ luật tự thân không cần gồng.", "thumbnail": "https://traicainghien.com/images/articles/4-hoa-chat-than-kinh-can-bang-nao-bo-zen.webp", "points": ["Nhịp tim tăng nhẹ, các mạch máu dẫn truyền oxy dồi dào lên não bộ.", "Toàn bộ các giác quan được kích hoạt, bạn cảm thấy mình có năng lượng và sẵn sàng hành động.", "Uống 3 - 4 ly cà phê đậm đặc khi bụng đói khiến Epinephrine vọt lên quá cao, vượt ngưỡng chịu đựng sinh học, chuyển hóa thành cảm giác bồn chồn, tim đập thình thịch, lo âu và run tay."], "action": "Dành 2 phút ghi lại cảm giác hiện tại và đặt điện thoại xa tầm mắt 2 mét.", "url": "https://traicainghien.com/bai-viet/bang-dieu-khien-nao-bo-4-hoa-chat-than-kinh-ky-luat-dinh-cao"}, {"slug": "giao-thuc-huberman-biohacking-nao-bo-tap-trung-dinh-cao", "title": "Giao Thức Huberman: 4 Thói Quen Cho Não Bộ Tập Trung Đỉnh Cao", "excerpt": "Ánh sáng sớm, nhịp 90 phút, thở dài sinh lý và NSDR: 4 công cụ khoa học thần kinh từ GS Andrew Huberman giúp bạn khôi phục sự tập trung và xua tan sương mù não.", "thumbnail": "https://traicainghien.com/images/articles/biohacking-nao-bo-tap-trung-huberman-zen-trai-cai-nghien.webp", "points": ["Acetylcholine:** Đóng vai trò như một chiếc đèn rọi tiêu điểm, làm nổi bật thông tin bạn đang xử lý và gạt bỏ mọi tạp âm xao nhãng xung quanh.", "Dopamine:** Đóng vai trò là nguồn nhiên liệu tạo ra động lực, sự khao khát tiến về phía trước và cảm giác thỏa mãn khi hoàn thành mục tiêu.", "Tế bào này gửi tín hiệu thẳng đến <b>nhân trên chéo (Suprachiasmatic Nucleus - SCN)</b> — đồng hồ sinh học trung ương của não bộ."], "action": "Chỉ mở đúng 1 tab trình duyệt duy nhất trong 25 phút làm việc kế tiếp.", "url": "https://traicainghien.com/bai-viet/giao-thuc-huberman-biohacking-nao-bo-tap-trung-dinh-cao"}, {"slug": "dopamine-detox-7-ngay-thao-go-kich-thich-re-tien", "title": "Dopamine Detox 7 Ngày: Lấy Lại Cảm Hứng Với Những Việc Khó", "excerpt": "Nguyên lý nước đục để yên sẽ tự trong: Lộ trình 7 ngày thanh lọc dopamine giúp tái thiết lập thụ thể D2, xóa tan cảm giác uể oải và tìm lại niềm vui lao động.", "thumbnail": "https://traicainghien.com/images/articles/dopamine-detox-7-ngay-zen-watercolor-v2.webp", "points": ["Tắt 100% thông báo không thiết yếu:** Tắt thông báo Facebook, TikTok, Instagram, sàn thương mại điện tử. Chỉ giữ lại chuông cuộc gọi khẩn cấp từ gia đình và công việc.", "Quy tắc 2 mét khi ngủ:** Cắm sạc điện thoại ở một chiếc bàn cách xa giường ít nhất 2 mét. Điều này triệt tiêu hoàn toàn thói quen với tay lướt màn hình trước khi ngủ và ngay khi vừa mở mắt.", "Quy tắc 60 phút buổi sáng:** Không chạm vào màn hình số trong 60 phút đầu tiên của ngày. Dùng khoảng thời gian này để rửa mặt, uống một ly nước ấm, vươn vai và ngắm nhìn bầu trời."], "action": "Tắt mọi thông báo không quan trọng và chuyển màn hình điện thoại về thang xám.", "url": "https://traicainghien.com/bai-viet/dopamine-detox-7-ngay-thao-go-kich-thich-re-tien"}, {"slug": "chung-ta-dang-song-vi-dieu-gi-giai-ma-khung-hoang-hien-sinh", "title": "Chúng Ta Đang Sống Vì Điều Gì: Vượt Qua Khủng Hoảng Hiện Sinh", "excerpt": "Cảm giác trống rỗng mỗi sáng thức dậy dù vẫn đủ đầy vật chất: Tự vấn hiện sinh cùng câu chuyện Dế Mèn Du Ký và 4 tầng nhu cầu tìm lại lẽ sống đích thực.", "thumbnail": "https://traicainghien.com/images/articles/chung-ta-dang-song-vi-dieu-gi-hien-nha-zen-v2.webp", "points": ["Cách bạn thức dậy vào sáng sớm và mỉm cười với ngày mới.", "Cách bạn tận tụy làm tốt công việc của mình dù không có ai giám sát.", "Cách bạn chọn buông bỏ chiếc điện thoại để lắng nghe trọn vẹn câu chuyện của người thân."], "action": "Dành 2 phút ghi lại cảm giác hiện tại và đặt điện thoại xa tầm mắt 2 mét.", "url": "https://traicainghien.com/bai-viet/chung-ta-dang-song-vi-dieu-gi-giai-ma-khung-hoang-hien-sinh"}, {"slug": "doc-sach-di-tim-le-song-chiec-phao-cuu-sinh-nghich-canh", "title": "Đọc 'Đi Tìm Lẽ Sống' - Chiếc Phao Cứu Sinh Giữa Nghịch Cảnh", "excerpt": "Giữa tận cùng địa ngục trại tập trung Auschwitz, điều gì đã giúp con người sống sót? Cuốn sách kinh điển của Viktor Frankl trao cho bạn chiếc phao cứu sinh để vượt qua mọi khủng hoảng hiện sinh...", "thumbnail": "https://traicainghien.com/images/articles/sach-di-tim-le-song-viktor-frankl-zen-trai-cai-nghien.webp", "points": ["Tất cả áo quần, kỷ vật, giấy tờ tùy thân và bản thảo công trình nghiên cứu cả đời của Frankl bị ném vào lò thiêu ngay trong đêm đầu tiên bước vào cổng trại.", "Toàn bộ tóc và lông trên cơ thể bị cạo sạch. Ông bị tước luôn cả tên họ của mình, chỉ còn lại một mã số tù nhân: <b>Số 119.104</b>.", "Cha mẹ, anh trai và người vợ trẻ đang mang thai của ông lần lượt bị đưa vào phòng hơi ngạt hoặc chết vì kiệt sức."], "action": "Chọn đúng 1 ý tưởng hay nhất từ cuốn sách đang đọc và đem ra áp dụng ngay.", "url": "https://traicainghien.com/bai-viet/doc-sach-di-tim-le-song-chiec-phao-cuu-sinh-nghich-canh"}, {"slug": "doc-cau-chuyen-dong-song-buong-bo-tim-kiem-de-that-su-thay", "title": "Đọc 'Câu Chuyện Dòng Sông' - Buông Bỏ Tìm Kiếm Để Thật Sự Thấy", "excerpt": "Càng mải miết đi tìm bình an ta lại càng kiệt sức? Kiệt tác 'Câu Chuyện Dòng Sông' của Hermann Hesse hé lộ bí mật: Ngừng tìm kiếm để thực sự nhìn thấy...", "thumbnail": "https://traicainghien.com/images/articles/sach-cau-chuyen-dong-song-siddhartha-zen-trai-cai-nghien.webp", "points": ["Phi thời gian:* Quá khứ và tương lai chỉ là ảo tưởng; nỗi đau chỉ tồn tại khi tâm trí rời xa hiện tại.", "Không phán xét:* Ôm trọn cả hoa thơm lẫn rác rưởi, bao dung chấp nhận mọi vết sẹo của quá khứ.", "Hợp âm vạn vật:* Muôn vàn thanh âm vui buồn, thiện ác hợp thành tiếng 'OM' duy nhất của sự sống."], "action": "Dành 2 phút ghi lại cảm giác hiện tại và đặt điện thoại xa tầm mắt 2 mét.", "url": "https://traicainghien.com/bai-viet/doc-cau-chuyen-dong-song-buong-bo-tim-kiem-de-that-su-thay"}, {"slug": "tinh-deo-than-kinh-tai-lap-trinh-bo-nao-chinh-phuc-viec-kho", "title": "Tính Dẻo Thần Kinh: Cách 'Tái Lập Trình' Não Chinh Phục Việc Khó", "excerpt": "Sau 25 tuổi não bộ sẽ ngừng phát triển và khó học việc mới? Khám phá bí mật Tính dẻo thần kinh (Neuroplasticity) và cẩm nang 4 bước tái lập trình bộ não...", "thumbnail": "https://traicainghien.com/images/articles/tinh-deo-than-kinh-athlete-zen-watercolor.webp", "points": ["Hóa học:* Tăng dẫn truyền thần kinh tức thì (trí nhớ ngắn hạn, dễ biến mất).", "Cấu trúc:* Tạo mới khớp nối synapse và bọc lớp Myelin dày đặc (trí nhớ dài hạn).", "Chức năng:* Tái cấu trúc và mở rộng các vùng não chuyên trách (như tài xế taxi London)."], "action": "Dành 2 phút ghi lại cảm giác hiện tại và đặt điện thoại xa tầm mắt 2 mét.", "url": "https://traicainghien.com/bai-viet/tinh-deo-than-kinh-tai-lap-trinh-bo-nao-chinh-phuc-viec-kho"}, {"slug": "tang-hieu-suat-khi-nao-bi-thoi-deep-work-chong-tri-tre", "title": "Tăng Hiệu Suất Khi Não Bị 'Thối': Cách Deep Work Chống Trì Trệ", "excerpt": "Ngồi vào bàn 5 phút đã vô thức quẹt TikTok đến trưa? Bạn không thiếu ý chí, não bạn đang mắc kẹt trong bẫy 'bận rộn ảo' và nhũn não số. Đây là quy trình 4 bước Deep Work thực chiến...", "thumbnail": "https://traicainghien.com/images/articles/tang-hieu-suat-deep-work-zen-watercolor.webp", "points": ["Mục tiêu tiến trình & Daily Highlight:* Chọn duy nhất 1 việc quan trọng nhất trong ngày để đưa não vào trạng thái đơn nhiệm.", "Không gian tỉnh thức:* Tuyệt đối không làm việc trên giường; giữ tư thế ngồi tỉnh táo.", "Quy tắc 2 phút & 5 phút:* Việc dưới 2 phút làm ngay; việc khó cam kết làm đúng 5 phút để kích hoạt đà quán tính tâm lý."], "action": "Chỉ mở đúng 1 tab trình duyệt duy nhất trong 25 phút làm việc kế tiếp.", "url": "https://traicainghien.com/bai-viet/tang-hieu-suat-khi-nao-bi-thoi-deep-work-chong-tri-tre"}, {"slug": "quy-tac-2-met-thay-doi-khong-can-y-chi", "title": "Quy tắc 2 mét: Bỏ thói quen xấu không cần ý chí", "excerpt": "Ý chí chỉ là một bình ắc-quy cạn dần theo ngày. Thay vì cấm đoán, hãy thiết kế lại khoảng cách ổ cắm sạc bằng nghệ thuật Kaizen 1%...", "thumbnail": "https://traicainghien.com/images/articles/quy-tac-2-met-sac-pin-zen-trai-cai-nghien.webp", "points": ["Bạn không hề yếu đuối. Bạn không hề lười biếng. Và bạn tuyệt đối không phải là một kẻ suy đồi đạo đức hay thiếu ý chí!**", "Ý chí thực chất là một nguồn tài nguyên sinh học hữu hạn (Finite Biological Resource).**", "Kết quả: Nhóm được ăn bánh quy thoải mái đã kiên trì thử giải bài toán trong suốt <b>20 phút</b>."], "action": "Dành 2 phút ghi lại cảm giác hiện tại và đặt điện thoại xa tầm mắt 2 mét.", "url": "https://traicainghien.com/bai-viet/quy-tac-2-met-thay-doi-khong-can-y-chi"}, {"slug": "bo-do-nghe-sinh-ton-so-5-cong-cu-cai-nghien", "title": "5 công cụ miễn phí chặn đứng cám dỗ màn hình", "excerpt": "Ý chí là tài nguyên hữu hạn. Khi cơn thèm quẹt máy ập đến lúc nửa đêm, bạn cần những 'bức tường lửa' kỹ thuật số để can thiệp kịp thời...", "thumbnail": "https://traicainghien.com/images/articles/5-cong-cu-chan-cam-do-man-hinh-zen-trai-cai-nghien.webp", "points": ["\"Tại sao mình lại không thể tập trung nổi dù chỉ 15 phút? Tại sao đầu óc mình cứ như một bầy khỉ nhảy nhót lung tung từ cành này sang cành khác? Mình bị ADHD rồi sao? Hay mình sinh ra đã là một kẻ vô kỷ luật, nghiện ngập không có thuốc chữa?\"*.", "Bạn không hề mắc bệnh tâm thần. Bạn cũng không hề thiếu kỷ luật.**", "Cách cài đặt trên iPhone (iOS):** Vào `Cài đặt` → `Trợ năng (Accessibility)` → `Màn hình & Cỡ chữ` → `Bộ lọc màu (Color Filters)` → Bật `Thang màu xám (Grayscale)`."], "action": "Dành 2 phút ghi lại cảm giác hiện tại và đặt điện thoại xa tầm mắt 2 mét.", "url": "https://traicainghien.com/bai-viet/bo-do-nghe-sinh-ton-so-5-cong-cu-cai-nghien"}, {"slug": "review-sach-bay-hanh-phuc-russ-harris", "title": "Đọc 'Bẫy Hạnh Phúc' - Càng Cố Vui Vẻ Càng Dễ Khổ Sở Và Nghiện", "excerpt": "Bạn bị ép phải luôn suy nghĩ tích cực, luôn nở nụ cười? Càng cố né tránh nỗi buồn, bạn càng lao vào lướt mạng, ăn vặt để trốn chạy. Đây là cách thoát khỏi chiếc bẫy tinh vi nhất của tâm trí...", "thumbnail": "https://traicainghien.com/images/articles/sach-bay-hanh-phuc-trai-cai-nghien.webp", "points": ["Khi não nói: *\"Mày là một kẻ lười biếng vô dụng\"*, bạn tin rằng mình là kẻ lười biếng vô dụng.", "Khi não nói: *\"Mày không thể làm nổi việc này đâu\"*, bạn tê liệt và bỏ cuộc.", "Suy nghĩ và cái tôi của bạn dính chặt vào nhau như hai giọt nước hòa làm một."], "action": "Dành 2 phút ghi lại cảm giác hiện tại và đặt điện thoại xa tầm mắt 2 mét.", "url": "https://traicainghien.com/bai-viet/review-sach-bay-hanh-phuc-russ-harris"}, {"slug": "6-buoc-can-lam-khi-con-them-ap-den-urge-surfing", "title": "Urge Surfing: 6 bước lướt trên cơn thèm mà không ngã", "excerpt": "Cơn thèm bấm máy hay ăn ngọt giống hệt như một ngọn sóng biển: Nó dâng lên, đạt đỉnh trong 3 phút rồi tự động xẹp xuống. Quy trình 6 bước cấp cứu...", "thumbnail": "https://traicainghien.com/images/articles/6-buoc-urge-surfing-trai-cai-nghien.webp", "points": ["\"Chỉ một lần này nữa thôi!\", \"Lướt đúng 5 phút thôi rồi ngủ!\", \"Hút đúng 1 điếu này thôi rồi mai bỏ thật!\", \"Ăn nốt cái bánh này rồi mai tập bù!\"*.", "Bạn không thể dùng bạo lực ý chí để đàn áp một cơn thèm sinh học. Bạn cũng không cần phải đầu hàng nó.**", "Mọi cơn thèm muốn trong não bộ con người thực chất giống hệt như một NGỌN SÓNG BIỂN (Ocean Wave)!**"], "action": "Dành 2 phút ghi lại cảm giác hiện tại và đặt điện thoại xa tầm mắt 2 mét.", "url": "https://traicainghien.com/bai-viet/6-buoc-can-lam-khi-con-them-ap-den-urge-surfing"}, {"slug": "review-sach-bay-so-hai-vuot-qua-tri-hoan", "title": "Đọc 'Bẫy Sợ Hãi' - Bạn Không Hề Lười, Bạn Đang Sợ Cuộc Đời Mình", "excerpt": "Cứ ngồi vào bàn làm việc 5 phút là lại thò tay lướt TikTok? Gốc rễ của sự trì hoãn không phải vì bạn vô kỷ luật, mà là vì một nỗi sợ vô hình đang điều khiển hạch hạnh nhân của bạn...", "thumbnail": "https://traicainghien.com/images/articles/sach-bay-so-hai-tri-hoan-zen-trai-cai-nghien.webp", "points": ["Mở tab TikTok hoặc Facebook Reels.**", "Bấm xem các video review đồ công nghệ.**", "Dọn dẹp bàn làm việc lần thứ ba trong ngày.**"], "action": "Dành 2 phút ghi lại cảm giác hiện tại và đặt điện thoại xa tầm mắt 2 mét.", "url": "https://traicainghien.com/bai-viet/review-sach-bay-so-hai-vuot-qua-tri-hoan"}, {"slug": "cai-bay-nghien-tich-luy-kien-thuc-tieu-thu-thu-dong", "title": "Bẫy Tích Lũy Kiến Thức: Vì Sao Càng Học Lại Càng Trì Hoãn?", "excerpt": "Lưu hàng trăm bài viết hay, xem hàng chục video podcast tâm lý học, mua hàng đống sách về để trên kệ... nhưng cuộc đời bạn vẫn giẫm chân tại chỗ? Đây là chiếc bẫy tinh vi nhất của não bộ mang tên 'Tiêu thụ thụ động'...", "thumbnail": "https://traicainghien.com/images/articles/cai-bay-tich-luy-kien-thuc-trai-cai-nghien.webp", "points": ["Người nói trên màn hình đã trải qua 10 năm vất vả, đọc hàng trăm cuốn sách, thất bại hàng chục lần để đúc kết ra bài học đó. Họ nói cực kỳ trôi chảy, logic và cuốn hút.", "Khi thông tin đó đi qua mắt và tai bạn một cách dễ dàng, bộ não lười biếng của bạn lập tức phạm phải một sai lầm chết người: <b>Nó đánh đồng việc \"Tôi HIỂU những gì anh ta nói\" với việc \"Tôi ĐÃ LÀM ĐƯỢC điều đó\"!</b>", "Bạn hoàn toàn chưa làm được cái gì cả!** Bạn chỉ là một khán giả đang ngồi vỗ tay cho thành tựu của người khác. Sự hiểu biết đó chỉ là một lớp bọt xà phòng mong manh, chỉ cần gió thổi qua là vỡ tan tành!"], "action": "Dành 2 phút ghi lại cảm giác hiện tại và đặt điện thoại xa tầm mắt 2 mét.", "url": "https://traicainghien.com/bai-viet/cai-bay-nghien-tich-luy-kien-thuc-tieu-thu-thu-dong"}, {"slug": "review-sach-flow-dong-chay-mihaly-csikszentmihalyi", "title": "Đọc 'Dòng Chảy' - Tìm Lại Sự Đắm Chìm Mà Màn Hình Ảo Không Có", "excerpt": "Đã bao lâu rồi bạn chưa có cảm giác làm một việc gì đó say mê đến mức quên cả thời gian, đói bụng hay tiếng điện thoại? Đây là bản đồ giải phẫu trạng thái thăng hoa cao nhất của bộ não con người...", "thumbnail": "https://traicainghien.com/images/articles/sach-flow-dong-chay-trai-cai-nghien.webp", "points": ["Không đòi hỏi bất kỳ nỗ lực nhận thức hay kỹ năng nào.** Bạn chỉ cần ngồi yên và đón nhận kích thích.", "Không tạo ra sự phát triển tâm lý.** Sau khi cơn khoái cảm qua đi, cái tôi của bạn không trưởng thành hơn chút nào.", "Quy luật hiệu dụng biên giảm dần (Hedonic Treadmill):<b> Liều lượng dopamine cũ sẽ nhanh chóng trở nên nhàm chán, buộc bạn phải tăng liều cao hơn để đạt được cùng một mức kích thích. Kết quả là nó dễ dàng biến tướng thành </b>Nghiện ngập**."], "action": "Dành 2 phút ghi lại cảm giác hiện tại và đặt điện thoại xa tầm mắt 2 mét.", "url": "https://traicainghien.com/bai-viet/review-sach-flow-dong-chay-mihaly-csikszentmihalyi"}, {"slug": "thanh-loc-nao-bo-de-lam-viec-sau", "title": "Thanh Lọc Não Bộ: Vì Sao Ta Chán Làm Việc Và Thèm Quẹt Máy?", "excerpt": "Mở laptop lên định làm việc, nhưng mới gõ được vài dòng là ngứa ngáy thò tay lấy điện thoại. Não bạn không bị hỏng, nó chỉ đang bị 'bội thực' Dopamine kích thích cao...", "thumbnail": "https://traicainghien.com/images/articles/thanh-loc-nao-bo-dopamine-detox-trai-cai-nghien.webp", "points": ["Rút toàn bộ dây sạc điện thoại ra khỏi đầu giường.", "Mang trạm sạc ra chiếc bàn cách giường ít nhất 2 mét.", "Mua một chiếc đồng hồ báo thức cơ học 50.000đ để cạnh gối."], "action": "Dành 2 phút ghi lại cảm giác hiện tại và đặt điện thoại xa tầm mắt 2 mét.", "url": "https://traicainghien.com/bai-viet/thanh-loc-nao-bo-de-lam-viec-sau"}, {"slug": "review-sach-bay-tien-nghi-michael-easter", "title": "Đọc 'Bẫy Tiện Nghi' - Sự Thừa Mứa Đang Giết Chết Nghị Lực Bạn", "excerpt": "33 ngày giữa băng tuyết Bắc Cực đã dạy Michael Easter một sự thật tàn nhẫn: Con người hiện đại đang chết dần vì... quá tiện nghi. Muốn thoát khỏi sự bồn chồn và nhũn não số, bạn phải học cách tự nguyện đón nhận sự khó chịu lành mạnh.", "thumbnail": "https://traicainghien.com/images/articles/sach-bay-tien-nghi-comfort-crisis-zen-trai-cai-nghien.webp", "points": ["Thức ăn cực kỳ khó kiếm: Tổ tiên chúng ta phải đi bộ hàng chục cây số mỗi ngày để săn bắn hoặc hái lượm. Vì vậy, bộ não tiến hóa để cài đặt một chương trình sinh tồn mãnh liệt: <b>Hãy ăn nhiều nhất có thể mỗi khi có đồ ăn (đặc biệt là đồ ngọt và chất béo để tích mỡ dự trữ), và hãy nghỉ ngơi nhiều nhất có thể để tiết kiệm calo!</b>", "Thời tiết khắc nghiệt: Mùa đông rét buốt cắt da cắt thịt, mùa hè nóng cháy da. Con người phải rèn luyện khả năng thích nghi nhiệt độ sinh học cực cao để sống sót.", "Mọi thứ đều đòi hỏi vận động thể chất nặng nhọc: Mang vác củi, khiêng đá, chạy trốn kẻ thù."], "action": "Dành 2 phút ghi lại cảm giác hiện tại và đặt điện thoại xa tầm mắt 2 mét.", "url": "https://traicainghien.com/bai-viet/review-sach-bay-tien-nghi-michael-easter"}, {"slug": "review-sach-tu-duy-nhanh-va-cham-daniel-kahneman", "title": "Đọc 'Tư Duy Nhanh & Chậm' - Vì Sao Ngón Tay Quẹt Trước Khi Nghĩ", "excerpt": "Cuốn sách kinh điển của nhà đoạt giải Nobel Daniel Kahneman bóc trần cuộc chiến ngầm giữa Hệ thống 1 bốc đồng và Hệ thống 2 chậm chạp — bí mật mà mọi ứng dụng mạng xã hội đều lợi dụng để biến bạn thành con nghiện...", "thumbnail": "https://traicainghien.com/images/articles/sach-tu-duy-nhanh-va-cham-trai-cai-nghien.webp", "points": ["Đặc tính:** Hoạt động tự động, tức thì, cảm tính, tiêu tốn cực kỳ ít năng lượng và hoàn toàn nằm ngoài tầm kiểm soát của ý thức.", "Nhiệm vụ tiến hóa:** Được hình thành từ thời đồ đá để giúp tổ tiên chúng ta đưa ra quyết định sinh tử trong chớp mắt (Nhìn thấy bóng đen giật mình nhảy lùi lại; nghe tiếng gầm rú bỏ chạy ngay; nhìn thấy hoa quả chín ngọt là lao vào hái ăn).", "Biểu hiện đời thường:**"], "action": "Dành 2 phút ghi lại cảm giác hiện tại và đặt điện thoại xa tầm mắt 2 mét.", "url": "https://traicainghien.com/bai-viet/review-sach-tu-duy-nhanh-va-cham-daniel-kahneman"}, {"slug": "bo-nao-thoi-do-da-bay-dan-va-nghe-thuat-tu-duy-nguoc-charlie-munger", "title": "Charlie Munger & Darwin: Bộ Não Đồ Đá Và Thuật Tư Duy Ngược", "excerpt": "Tại sao những người rất thông minh lại liên tục đưa ra quyết định sai lầm thảm họa? Giải phẫu cỗ máy sinh tồn đồ đá trong não bộ người hiện đại và nghệ thuật tư duy ngược giúp bạn bớt ngu ngốc để giành lại tự do.", "thumbnail": "https://traicainghien.com/images/articles/tu-duy-nguoc-charlie-munger-trai-cai-nghien.webp", "points": ["Phản ứng nhanh hơn suy nghĩ:** Nghe tiếng động sột soạt trong lùm cây? Chạy ngay lập tức! Kẻ nào đứng lại phân tích xem đó là con hổ răng kiếm hay chỉ là ngọn gió lay sẽ bị ăn thịt trước khi kịp truyền lại bộ gene cho đời sau.\\r", "Tích trữ năng lượng tối đa:** Thức ăn thời đó vô cùng khan hiếm. Bất cứ khi nào nhìn thấy thứ gì ngọt, béo, nhiều calo, não bộ lập tức kích hoạt bản năng nhồi nhét cật lực và nằm im nghỉ ngơi để tiết kiệm từng giọt năng lượng.\\r", "Bám chặt lấy bầy đàn:** Một cá thể nguyên thủy bị trục xuất khỏi bộ tộc đồng nghĩa với một bản án tử hình chắc chắn. Hoặc bạn chết đói, hoặc bạn làm mồi cho thú dữ. Vì vậy, nỗi sợ bị cô lập, nhu cầu được bầy đàn chấp nhận và xu hướng làm theo đám đông đã được khắc sâu vào tận tủy sống.\\r"], "action": "Cất điện thoại ngoài phòng ngủ hoặc cách giường tối thiểu 2 mét.", "url": "https://traicainghien.com/bai-viet/bo-nao-thoi-do-da-bay-dan-va-nghe-thuat-tu-duy-nguoc-charlie-munger"}, {"slug": "review-sach-kaizen-1-phan-tram-moi-ngay", "title": "Đọc 'Kaizen' - Nhích 1% Mỗi Ngày Để Đánh Lừa Não Bộ Của Bạn", "excerpt": "Cứ mỗi lần hạ quyết tâm dậy 5h sáng hay tập gym là y như rằng bỏ cuộc sau 3 ngày? Hãy ngừng dùng búa tạ đập vào não bộ. Đây là cách người Nhật thay đổi cả một đời bằng những bước đi vi mô nhẹ tênh...", "thumbnail": "https://traicainghien.com/images/articles/sach-kaizen-1-phan-tram-zen-trai-cai-nghien.webp", "points": ["\"Từ ngày mai, mình sẽ thức dậy lúc 5h00 sáng để chạy bộ 5km!\"*", "\"Mình sẽ ngừng ăn toàn bộ đồ ngọt, kiêng hoàn toàn tinh bột để giảm 10kg trong 1 tháng!\"*", "\"Mỗi ngày mình sẽ đọc đúng 50 trang sách và học tiếng Anh 2 tiếng!\"*"], "action": "Bắt đầu với phiên bản 2 phút cực nhỏ cho việc bạn đang trì hoãn.", "url": "https://traicainghien.com/bai-viet/review-sach-kaizen-1-phan-tram-moi-ngay"}, {"slug": "2-quy-tac-don-gian-cai-thien-su-tap-trung", "title": "2 quy tắc đơn giản để cải thiện sự tập trung không cần gồng ép", "excerpt": "Mở máy ra định học, nhưng cứ 5 phút lại với tay cầm điện thoại? Đừng cố luyện 'ý chí sắt đá'. Đây là 2 quy tắc ma sát hành vi giúp bạn làm việc sâu nhẹ tênh...", "thumbnail": "https://traicainghien.com/images/articles/2-quy-tac-cai-thien-tap-trung-trai-cai-nghien.webp", "points": ["Bước 1: Cuộc thanh trừng buổi sáng (The Morning Tab Purge):**", "Bước 2: Chế độ toàn màn hình (Full-Screen Mode - Phím F11):**", "Bước 3: Nguyên tắc \"Muốn mở tab mới thì phải đóng tab cũ\":**"], "action": "Chỉ mở đúng 1 tab trình duyệt duy nhất trong 25 phút làm việc kế tiếp.", "url": "https://traicainghien.com/bai-viet/2-quy-tac-don-gian-cai-thien-su-tap-trung"}, {"slug": "review-sach-ikigai-di-tim-le-song", "title": "Đọc 'Ikigai' - Có Một Lý Do Thức Dậy, Đồ Rẻ Tiền Tự Khắc Vô Vị", "excerpt": "Tại sao người già ở ngôi làng trường thọ Ogimi (Okinawa) không bao giờ biết đến khái niệm nghỉ hưu hay trầm cảm? Bí mật không nằm ở nhân sâm hay thuốc bổ, mà nằm ở một hạt mầm mang tên Ikigai...", "thumbnail": "https://traicainghien.com/images/articles/sach-ikigai-di-tim-le-song-zen-trai-cai-nghien.webp", "points": ["Chỉ có Đam mê + Kỹ năng giỏi:** Bạn cảm thấy thỏa mãn bên trong nhưng rỗng túi, bất an tài chính (Hội chứng \"Nghệ sĩ nghèo\").", "Chỉ có Kỹ năng giỏi + Kiếm nhiều tiền:** Bạn giàu có, thành đạt nhưng luôn cảm thấy trống rỗng vô nghĩa, tâm hồn chai sạn (Hội chứng \"Cổ cồn trắng kiệt sức\").", "Chỉ có Kiếm tiền + Thế giới cần:** Bạn có công việc ổn định, làm việc thiện nguyện nhưng không phát huy được năng lực, cảm thấy mình chỉ là một bánh răng tầm thường dễ bị thay thế."], "action": "Dành 2 phút ghi lại cảm giác hiện tại và đặt điện thoại xa tầm mắt 2 mét.", "url": "https://traicainghien.com/bai-viet/review-sach-ikigai-di-tim-le-song"}, {"slug": "phuong-phap-nang-luong-musashi-tri-kiet-que-tinh-than", "title": "Bí Mật Musashi: Chấm Dứt Kiệt Quệ Tinh Thần Cho Người Hay Mệt", "excerpt": "Bạn ngủ đủ 8 tiếng nhưng sáng dậy vẫn mệt như đeo chì? Bạn không ốm đau nhưng lúc nào cũng thấy kiệt sức, uể oải? Đây là bí mật quản trị năng lượng sinh học từ kiếm thánh Miyamoto Musashi giúp bạn tìm lại thần khí tĩnh tại...", "thumbnail": "https://traicainghien.com/images/articles/phuong-phap-nang-luong-musashi-trai-cai-nghien.webp", "points": ["Từ năm 13 tuổi đến năm 29 tuổi, ông đã tham gia hơn <b>60 trận quyết đấu sinh tử</b> một chọi một bằng kiếm thật, và chưa từng thua một trận nào!", "Trong những trận chiến đó, chỉ cần một tích tắc phân tâm, một thoáng run rẩy hay một giây mệt mỏi lơ là... đầu của ông sẽ rơi xuống đất ngay lập tức!", "Ông phải liên tục di chuyển ròng rã khắp nước Nhật, ngủ dưới gầm cầu, trong hang đá, dầm mưa dãi nắng giữa rừng sâu. Về già, ông một mình ẩn cư trong hang Reigando, vừa nhịn ăn, vừa ngồi thiền tạc tượng Phật và viết nên kiệt tác binh pháp *Ngũ Luân Thư (The Book of Five Rings)*."], "action": "Hạ chuẩn mọi mục tiêu xuống mức tối thiểu, cho phép bản thân nghỉ ngơi sớm.", "url": "https://traicainghien.com/bai-viet/phuong-phap-nang-luong-musashi-tri-kiet-que-tinh-than"}, {"slug": "review-sach-deep-work-cal-newport", "title": "Đọc 'Deep Work' - Tấm Khiên Bảo Vệ Tâm Trí Khỏi Xao Nhãng Số", "excerpt": "Trong một thế giới mà ai cũng nhảy tab liên tục và trả lời tin nhắn sau 3 giây, năng lực ngồi yên làm việc sâu 90 phút chính là thứ phân chia người làm chủ cuộc chơi và kẻ làm nô lệ cho thuật toán...", "thumbnail": "https://traicainghien.com/images/articles/sach-deep-work-lam-sau-trai-cai-nghien.webp", "points": ["Viễn cảnh thứ nhất:**", "Đặc điểm:** Bất kỳ ai cũng có thể làm được và rất dễ bị thay thế bởi trí tuệ nhân tạo 